package com.iminiapp.backend.vehicle.application;

import com.iminiapp.backend.identity.web.AuthenticatedPrincipal;
import com.iminiapp.backend.shared.error.*;
import com.iminiapp.backend.shared.security.SensitiveDataCipher;
import com.iminiapp.backend.vehicle.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDateTime;
import java.util.*;

@Service
public class VehicleFleetManagementService {
 private final JdbcTemplate jdbc; private final SensitiveDataCipher cipher; private final VehicleSensitiveDataReader sensitiveReader;
 public VehicleFleetManagementService(JdbcTemplate jdbc,SensitiveDataCipher cipher){this.jdbc=jdbc;this.cipher=cipher;this.sensitiveReader=new VehicleSensitiveDataReader(cipher);}
 @Transactional public VehicleModelResponse createModel(AuthenticatedPrincipal p,VehicleModelUpsertRequest r){validateModel(r);long op=user(p);String code=r.modelCode().trim().toUpperCase(Locale.ROOT);if(count("SELECT COUNT(*) FROM bf_vehicle_model WHERE model_code=?",code)>0)throw new BusinessException(CommonErrorCode.CONFLICT,"车型编码已存在");KeyHolder h=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO bf_vehicle_model(model_code,name,seat_count,fuel_type,status) VALUES (?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setString(1,code);s.setString(2,r.name().trim());s.setInt(3,r.seatCount());s.setString(4,upper(r.fuelType(),"GASOLINE_OR_DIESEL"));s.setString(5,upper(r.status(),"ACTIVE"));return s;},h);long id=key(h);audit(op,"VEHICLE_MODEL_CREATE","VEHICLE_MODEL",id);return model(id);}
 @Transactional(readOnly=true) public List<VehicleModelResponse> models(){return jdbc.query("SELECT id,model_code,name,seat_count,fuel_type,status FROM bf_vehicle_model ORDER BY status,id",(rs,n)->new VehicleModelResponse(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getInt(4),rs.getString(5),rs.getString(6)));}
 @Transactional public VehicleModelResponse updateModel(AuthenticatedPrincipal p,long id,VehicleModelUpsertRequest r){validateModel(r);VehicleModelResponse current=model(id);String requestedCode=r.modelCode().trim().toUpperCase(Locale.ROOT);if(!current.modelCode().equals(requestedCode))throw new BusinessException(CommonErrorCode.CONFLICT,"车型编码创建后不可修改，避免历史订单失联");long op=user(p);int n=jdbc.update("UPDATE bf_vehicle_model SET name=?,seat_count=?,fuel_type=?,status=? WHERE id=?",r.name().trim(),r.seatCount(),upper(r.fuelType(),"GASOLINE_OR_DIESEL"),upper(r.status(),"ACTIVE"),id);if(n!=1)throw new BusinessException(CommonErrorCode.NOT_FOUND,"车型不存在");jdbc.update("UPDATE bf_resource r JOIN bf_resource_sku s ON s.resource_id=r.id SET r.name=CONCAT('社会租赁-',?),s.name=CONCAT(?,'社会租赁') WHERE s.sku_code=CONCAT('VEHICLE_RENTAL_',?)",r.name().trim(),r.name().trim(),requestedCode);audit(op,"VEHICLE_MODEL_UPDATE","VEHICLE_MODEL",id);return model(id);}
 @Transactional public VehicleResponse createVehicle(AuthenticatedPrincipal p,VehicleCreateRequest r){if(r==null||r.modelId()==null)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"modelId 不能为空");String vehicleNo=required(r.vehicleNo(),"vehicleNo",32),plate=required(r.plateNo(),"plateNo",32);if(count("SELECT COUNT(*) FROM bf_vehicle_model WHERE id=?",r.modelId())==0)throw new BusinessException(CommonErrorCode.NOT_FOUND,"车型不存在");if(count("SELECT COUNT(*) FROM bf_vehicle WHERE vehicle_no=? OR plate_no=?",vehicleNo,plate)>0)throw new BusinessException(CommonErrorCode.CONFLICT,"车辆编号或车牌号已存在");String config=json(r.configuration());BigDecimal mileage=r.mileageKm()==null?BigDecimal.ZERO:r.mileageKm();if(mileage.signum()<0)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"里程不能为负数");long op=user(p);KeyHolder h=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO bf_vehicle(model_id,vehicle_no,plate_no,image_url,configuration,status,mileage_km) VALUES (?,?,?,?,CAST(? AS JSON),?,?)",Statement.RETURN_GENERATED_KEYS);s.setLong(1,r.modelId());s.setString(2,vehicleNo);s.setString(3,plate);s.setString(4,optional(r.imageUrl(),512));s.setString(5,config);s.setString(6,upper(r.status(),"AVAILABLE"));s.setBigDecimal(7,mileage);return s;},h);long id=key(h);audit(op,"VEHICLE_CREATE","VEHICLE",id);return vehicle(id);}
 @Transactional public AdminVehicleDriverResponse createDriver(AuthenticatedPrincipal p,VehicleDriverCreateRequest r){if(r==null)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"请求体不能为空");String no=required(r.driverNo(),"driverNo",32),name=required(r.name(),"name",64),mobile=required(r.mobile(),"mobile",32),license=required(r.licenseNo(),"licenseNo",64);if(count("SELECT COUNT(*) FROM bf_driver WHERE driver_no=? OR license_no_hash=?",no,cipher.searchHash(license))>0)throw new BusinessException(CommonErrorCode.CONFLICT,"司机编号或驾驶证已存在");long op=user(p);KeyHolder h=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO bf_driver(driver_no,name_cipher,mobile_cipher,license_no_cipher,license_no_hash,status) VALUES (?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setString(1,no);s.setBytes(2,cipher.encrypt(name));s.setBytes(3,cipher.encrypt(mobile));s.setBytes(4,cipher.encrypt(license));s.setString(5,cipher.searchHash(license));s.setString(6,upper(r.status(),"AVAILABLE"));return s;},h);long id=key(h);audit(op,"VEHICLE_DRIVER_CREATE","DRIVER",id);return driver(id);}
 @Transactional public AdminVehicleDriverResponse updateDriverStatus(AuthenticatedPrincipal p,long id,String status){String s=upper(status,null);if(!Set.of("AVAILABLE","BUSY","INACTIVE").contains(s))throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"司机状态不正确");long op=user(p);if(jdbc.update("UPDATE bf_driver SET status=? WHERE id=?",s,id)!=1)throw new BusinessException(CommonErrorCode.NOT_FOUND,"司机不存在");audit(op,"VEHICLE_DRIVER_STATUS_UPDATE","DRIVER",id);return driver(id);}
 @Transactional public AdminVehicleDriverResponse bindDriverAccount(AuthenticatedPrincipal p,long id,DriverAccountBindingRequest r){if(r==null||r.userId()==null)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"userId 不能为空");if(count("SELECT COUNT(*) FROM bf_user WHERE id=? AND status='ACTIVE'",r.userId())==0)throw new BusinessException(CommonErrorCode.NOT_FOUND,"用户不存在或已停用");if(count("SELECT COUNT(*) FROM bf_driver WHERE user_id=? AND id<>?",r.userId(),id)>0)throw new BusinessException(CommonErrorCode.CONFLICT,"该用户已绑定其他司机档案");List<Long> oldUsers=jdbc.queryForList("SELECT user_id FROM bf_driver WHERE id=? AND user_id IS NOT NULL",Long.class,id);long op=user(p);if(jdbc.update("UPDATE bf_driver SET user_id=? WHERE id=?",r.userId(),id)!=1)throw new BusinessException(CommonErrorCode.NOT_FOUND,"司机不存在");if(!oldUsers.isEmpty()&&!Objects.equals(oldUsers.get(0),r.userId()))removeRole(oldUsers.get(0),"DRIVER");assignRole(r.userId(),"DRIVER");audit(op,"VEHICLE_DRIVER_ACCOUNT_BIND","DRIVER",id);return driver(id);}
 @Transactional public AdminVehicleDriverResponse unbindDriverAccount(AuthenticatedPrincipal p,long id){List<Long> users=jdbc.queryForList("SELECT user_id FROM bf_driver WHERE id=? AND user_id IS NOT NULL",Long.class,id);if(count("SELECT COUNT(*) FROM bf_driver WHERE id=?",id)==0)throw new BusinessException(CommonErrorCode.NOT_FOUND,"司机不存在");if(users.isEmpty())throw new BusinessException(CommonErrorCode.CONFLICT,"司机尚未绑定账号");if(count("SELECT COUNT(*) FROM bf_vehicle_dispatch WHERE driver_id=? AND status IN ('WAITING_DRIVER','ACCEPTED','IN_SERVICE')",id)>0)throw new BusinessException(CommonErrorCode.CONFLICT,"司机存在进行中的任务，暂不能解绑");long op=user(p);jdbc.update("UPDATE bf_driver SET user_id=NULL WHERE id=?",id);removeRole(users.get(0),"DRIVER");audit(op,"VEHICLE_DRIVER_ACCOUNT_UNBIND","DRIVER",id);return driver(id);}
 @Transactional public VehicleUnavailablePeriodResponse addUnavailable(AuthenticatedPrincipal p,long vehicleId,VehicleUnavailablePeriodRequest r){if(r==null||r.startAt()==null||r.endAt()==null||!r.endAt().isAfter(r.startAt()))throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"不可租时间不正确");if(count("SELECT COUNT(*) FROM bf_vehicle WHERE id=?",vehicleId)==0)throw new BusinessException(CommonErrorCode.NOT_FOUND,"车辆不存在");if(count("SELECT COUNT(*) FROM bf_vehicle_dispatch d JOIN bf_vehicle_booking b ON b.order_item_id=d.order_item_id WHERE d.vehicle_id=? AND d.status IN ('WAITING_DRIVER','ACCEPTED','IN_SERVICE') AND b.start_at<? AND b.end_at>?",vehicleId,r.endAt(),r.startAt())>0)throw new BusinessException(CommonErrorCode.CONFLICT,"该时段已有派车任务");long op=user(p);KeyHolder h=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO bf_vehicle_unavailable_period(vehicle_id,start_at,end_at,reason) VALUES (?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setLong(1,vehicleId);s.setObject(2,r.startAt());s.setObject(3,r.endAt());s.setString(4,optional(r.reason(),255));return s;},h);long id=key(h);audit(op,"VEHICLE_UNAVAILABLE_CREATE","VEHICLE_UNAVAILABLE",id);return period(id);}
 @Transactional public VehicleUnavailablePeriodResponse cancelUnavailable(AuthenticatedPrincipal p,long id){long op=user(p);if(jdbc.update("UPDATE bf_vehicle_unavailable_period SET status='CANCELLED' WHERE id=? AND status='ACTIVE'",id)!=1)throw new BusinessException(CommonErrorCode.CONFLICT,"不可租时段不存在或已取消");audit(op,"VEHICLE_UNAVAILABLE_CANCEL","VEHICLE_UNAVAILABLE",id);return period(id);}
 @Transactional(readOnly=true) public List<VehicleUnavailablePeriodResponse> periods(long vehicleId){return jdbc.query("SELECT id,vehicle_id,start_at,end_at,reason,status FROM bf_vehicle_unavailable_period WHERE vehicle_id=? ORDER BY start_at DESC",(rs,n)->periodMap(rs),vehicleId);}
 private void validateModel(VehicleModelUpsertRequest r){if(r==null||!StringUtils.hasText(r.modelCode())||!StringUtils.hasText(r.name())||r.seatCount()==null||r.seatCount()<1||r.seatCount()>100)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"车型编码、名称和1至100座座位数不能为空");}
 private VehicleModelResponse model(long id){return jdbc.queryForObject("SELECT id,model_code,name,seat_count,fuel_type,status FROM bf_vehicle_model WHERE id=?",(rs,n)->new VehicleModelResponse(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getInt(4),rs.getString(5),rs.getString(6)),id);}
 private VehicleResponse vehicle(long id){return jdbc.queryForObject("SELECT v.id,v.vehicle_no,v.plate_no,m.model_code,m.name,m.seat_count,v.status,v.mileage_km FROM bf_vehicle v JOIN bf_vehicle_model m ON m.id=v.model_id WHERE v.id=?",(rs,n)->new VehicleResponse(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getInt(6),rs.getString(7),rs.getBigDecimal(8)),id);}
 private AdminVehicleDriverResponse driver(long id){return jdbc.queryForObject("SELECT id,driver_no,name_cipher,mobile_cipher,user_id,status FROM bf_driver WHERE id=?",(rs,n)->{long userId=rs.getLong(5);return new AdminVehicleDriverResponse(rs.getLong(1),rs.getString(2),sensitiveReader.maskedName(rs.getBytes(3)),sensitiveReader.maskedMobile(rs.getBytes(4)),rs.wasNull()?null:userId,rs.getString(6));},id);}
 private VehicleUnavailablePeriodResponse period(long id){return jdbc.queryForObject("SELECT id,vehicle_id,start_at,end_at,reason,status FROM bf_vehicle_unavailable_period WHERE id=?",(rs,n)->periodMap(rs),id);} private VehicleUnavailablePeriodResponse periodMap(ResultSet rs)throws SQLException{return new VehicleUnavailablePeriodResponse(rs.getLong(1),rs.getLong(2),rs.getObject(3,LocalDateTime.class),rs.getObject(4,LocalDateTime.class),rs.getString(5),rs.getString(6));}
 private int count(String sql,Object...a){Integer n=jdbc.queryForObject(sql,Integer.class,a);return n==null?0:n;} private long key(KeyHolder h){if(h.getKey()==null)throw new BusinessException(CommonErrorCode.INTERNAL_ERROR,"数据创建失败");return h.getKey().longValue();}
 private String json(String v){if(!StringUtils.hasText(v))return "{}";Integer ok=jdbc.queryForObject("SELECT JSON_VALID(?)",Integer.class,v);if(ok==null||ok!=1)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"configuration 必须是合法JSON");return v;}
 private String required(String v,String f,int max){if(!StringUtils.hasText(v)||v.trim().length()>max)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,f+" 不能为空且最长"+max+"字符");return v.trim();} private String optional(String v,int max){if(!StringUtils.hasText(v))return null;if(v.trim().length()>max)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"字段最长"+max+"字符");return v.trim();} private String upper(String v,String d){return StringUtils.hasText(v)?v.trim().toUpperCase(Locale.ROOT):d;}
    private long user(AuthenticatedPrincipal p){if("ADMIN".equals(p.accountType())){try{return Long.parseLong(p.userId());}catch(RuntimeException ex){throw new BusinessException(CommonErrorCode.FORBIDDEN,"管理员身份无效");}}jdbc.update("INSERT INTO bf_user(wechat_openid,nickname,status) VALUES (?,?,'ACTIVE') ON DUPLICATE KEY UPDATE nickname=VALUES(nickname)",p.databaseOpenId(),p.displayName());return jdbc.queryForObject("SELECT id FROM bf_user WHERE wechat_openid=?",Long.class,p.databaseOpenId());}
 private void assignRole(long userId,String role){jdbc.update("INSERT IGNORE INTO bf_user_role(user_id,role_id) SELECT ?,id FROM bf_role WHERE code=?",userId,role);} private void removeRole(long userId,String role){jdbc.update("DELETE ur FROM bf_user_role ur JOIN bf_role r ON r.id=ur.role_id WHERE ur.user_id=? AND r.code=?",userId,role);} private void audit(long op,String action,String type,long id){jdbc.update("INSERT INTO bf_audit_log(operator_id,action,target_type,target_id,detail) VALUES (?,?,?,?,JSON_OBJECT())",op,action,type,String.valueOf(id));}
}
